import java.util.*;

public class Main {
    static int shortestPathLength(List<List<Integer>> graph) {
        int n = graph.size();
        int full = (1 << n) - 1;
        Queue<int[]> queue = new LinkedList<>();
        Set<Long> visited = new HashSet<>();
        for (int i = 0; i < n; i++) {
            queue.add(new int[]{i, 1 << i, 0});                      // start simultaneously from EVERY node
            visited.add((long) i * 5000 + (1 << i));
        }
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int node = cur[0], mask = cur[1], dist = cur[2];
            if (mask == full) return dist;                             // first time full mask is reached
            for (int nxt : graph.get(node)) {
                int nextMask = mask | (1 << nxt);
                long key = (long) nxt * 5000 + nextMask;
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.add(new int[]{nxt, nextMask, dist + 1});
                }
            }
        }
        return -1;
    }
}

