int shortestPathLength(vector<vector<int>>& graph) {
    int n = graph.size();
    int full = (1 << n) - 1;
    queue<tuple<int,int,int>> q;
    set<pair<int,int>> visited;
    for (int i = 0; i < n; i++) {
        q.push({i, 1 << i, 0});                                       // start simultaneously from EVERY node
        visited.insert({i, 1 << i});
    }
    while (!q.empty()) {
        auto [node, mask, dist] = q.front(); q.pop();
        if (mask == full) return dist;                                  // first time full mask is reached
        for (int nxt : graph[node]) {
            int nextMask = mask | (1 << nxt);
            if (!visited.count({nxt, nextMask})) {
                visited.insert({nxt, nextMask});
                q.push({nxt, nextMask, dist + 1});
            }
        }
    }
    return -1;
}
